<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { useRouter } from 'vue-router'
import { Plus, Upload, Search, Collection, Document, Reading, User, ArrowRight, Lock } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useWorkspace } from '../store'
import { request, post, showError } from '../api'
import { statusLabels } from '../types'
import type { DocumentRow, Library, Task } from '../types'
import PdfViewer from '../components/PdfViewer.vue'
import IndexMaintenance from '../components/IndexMaintenance.vue'
import LibraryStatusSummary from '../components/LibraryStatusSummary.vue'
import { documentStatusGroup, matchesDocumentStatus, type LibraryStatusFilter } from '../libraryStatus'
const ws = useWorkspace(), router = useRouter()
const documents = ref<DocumentRow[]>([]), selected = ref<DocumentRow[]>([]), detail = ref<DocumentRow | null>(null), query = ref(''), status = ref('all'), page = ref(1), loading = ref(false), uploading = ref(false), detailTab = ref('summary')
const createDialog = ref(false), title = ref(''), shared = ref(false), creating = ref(false), memberDialog = ref(false), members = ref<{ user_id: number; username: string; role: string }[]>([]), memberName = ref(''), memberRole = ref('viewer'), memberBusy = ref(false), fileInput = ref<HTMLInputElement>()
const library = computed(() => ws.libraries.find(l => l.id === ws.selectedLibrary))
const writable = computed(() => library.value && ['owner', 'editor'].includes(library.value.role))
const filtered = computed(() => documents.value.filter(d => matchesDocumentStatus(d, status.value) && `${d.paper_title || ''} ${d.filename}`.toLowerCase().includes(query.value.toLowerCase())))
const paged = computed(() => filtered.value.slice((page.value - 1) * 15, page.value * 15))
let generation = 0
function filterByStatus(value: LibraryStatusFilter) { query.value = ''; status.value = value }
function setSelection(rows: DocumentRow[]) { selected.value = rows }
function focusDocument(row: DocumentRow) { detail.value = row; detailTab.value = 'summary' }
function selectableDocument(row: DocumentRow) { return row.status === 'ready' }
async function load() { const token = ++generation; page.value = 1; selected.value = []; documents.value = []; detail.value = null; if (!ws.selectedLibrary) return; loading.value = true; try { const data = await request<DocumentRow[]>(`/libraries/${ws.selectedLibrary}/documents`); if (token === generation) { documents.value = data; detail.value = data[0] || null } } catch (e) { showError(e) } finally { if (token === generation) loading.value = false } }
async function create() { if (!title.value.trim()) return; creating.value = true; try { const item = await post<Library>('/libraries', { title: title.value.trim(), shared: shared.value }); await ws.refreshLibraries(); ws.selectedLibrary = item.id; createDialog.value = false; title.value = ''; shared.value = false; ElMessage.success('文献库已创建') } catch (e) { showError(e) } finally { creating.value = false } }
async function upload(event: Event) { const input = event.target as HTMLInputElement, files = Array.from(input.files || []); if (!writable.value || !files.length) return; uploading.value = true; let count = 0; try { for (const file of files) { if (!file.name.toLowerCase().endsWith('.pdf') || file.size > (ws.config?.max_pdf_mb || 50) * 1024 * 1024) { ElMessage.warning(`${file.name}：请选择不超过 ${ws.config?.max_pdf_mb || 50} MB 的 PDF`); continue }; const data = new FormData(); data.append('file', file); ws.track(await request<Task>(`/libraries/${ws.selectedLibrary}/documents`, { method: 'POST', body: data })); count++ }; if (count) ElMessage.success(`${count} 篇文献已进入处理队列，可在任务中心查看进度`) } catch (e) { showError(e) } finally { uploading.value = false; input.value = '' } }
async function study() { const ready = selected.value.filter(d => d.status === 'ready'); try { const session = await ws.createSession(ready.length ? `${ready.length} 篇文献研读` : `${library.value?.title || ''}研读`, ws.selectedLibrary); router.push({ path: '/read', query: { session: session.id, ...(ready.length ? { docs: ready.map(d => d.id).join(',') } : {}) } }) } catch (e) { showError(e) } }
async function openMembers() { memberDialog.value = true; try { members.value = await request(`/libraries/${ws.selectedLibrary}/members`) } catch (e) { showError(e) } }
async function addMember() { if (!memberName.value.trim()) return; memberBusy.value = true; try { await post(`/libraries/${ws.selectedLibrary}/members`, { username: memberName.value.trim(), role: memberRole.value }); memberName.value = ''; await openMembers(); ElMessage.success('成员权限已保存') } catch (e) { showError(e) } finally { memberBusy.value = false } }
async function removeMember(id: number) { try { await ElMessageBox.confirm('移除后，该成员将失去此共享库的访问权限。', '移除成员', { confirmButtonText: '移除', cancelButtonText: '取消', type: 'warning' }); await request(`/libraries/${ws.selectedLibrary}/members/${id}`, { method: 'DELETE' }); await openMembers() } catch (e) { if (e !== 'cancel' && e !== 'close') showError(e) } }
function refreshAfterTask(event: Event) { const task = (event as CustomEvent<Task>).detail; if (['upload', 'import', 'legacy_reindex'].includes(task.kind) && task.status === 'completed') load() }
watch(() => ws.selectedLibrary, load, { immediate: true })
watch([query, status], () => page.value = 1)
watch(filtered, rows => {
  if (!rows.some(row => row.id === detail.value?.id)) {
    detail.value = rows[0] || null
    detailTab.value = 'summary'
  }
})
onMounted(() => window.addEventListener('refmind:task-complete', refreshAfterTask))
onBeforeUnmount(() => { generation++; window.removeEventListener('refmind:task-complete', refreshAfterTask) })
</script>
<template><div class="library-page"><header class="page-heading"><div><div class="eyebrow">YOUR RESEARCH COLLECTION</div><h1>把重要文献，留在触手可及的地方</h1><p>管理个人与课题组文献，清楚掌握每篇论文的处理状态。</p></div><el-button @click="createDialog = true"><el-icon><Plus/></el-icon>新建文献库</el-button></header><div class="library-switcher"><button v-for="item in ws.libraries" :key="item.id" :class="['library-tile', { active: ws.selectedLibrary === item.id }]" @click="ws.selectedLibrary = item.id"><span class="library-tile-icon"><el-icon><Collection v-if="item.kind === 'shared'"/><Lock v-else/></el-icon></span><div><strong>{{ item.title }}</strong><small>{{ item.kind === 'shared' ? '课题组共享' : '我的私有文献' }} · {{ item.role === 'owner' ? '所有者' : item.role === 'editor' ? '可编辑' : '只读' }}</small></div></button><button class="library-tile add-library" @click="createDialog = true"><el-icon><Plus/></el-icon><span>创建新的文献库</span></button></div><section v-if="!library" class="large-empty"><span class="empty-search-symbol"><el-icon><Collection/></el-icon></span><h2>为你的研究建一个文献库</h2><p>私有库保存个人材料，共享库让课题组共同阅读。</p><el-button type="primary" @click="createDialog = true">创建第一个文献库</el-button></section><template v-else><LibraryStatusSummary :documents="documents" :selected="status" :loading="loading" @filter="filterByStatus"/><div class="library-section-header"><div><h2>{{ library.title }}</h2><span class="muted-text">{{ documents.length }} 篇文献 · {{ documents.filter(d => d.status === 'ready').length }} 篇可研读</span></div><div class="button-group"><el-button v-if="library.kind === 'shared' && library.role === 'owner'" @click="openMembers"><el-icon><User/></el-icon>管理成员</el-button><el-button :disabled="!documents.some(d => d.status === 'ready')" @click="study"><el-icon><Reading/></el-icon>{{ selected.length ? `研读所选 ${selected.filter(d => d.status === 'ready').length} 篇` : '研读文献库' }}</el-button><el-button v-if="writable" type="primary" :loading="uploading" @click="fileInput?.click()"><el-icon><Upload/></el-icon>上传 PDF</el-button><input ref="fileInput" class="visually-hidden" type="file" accept="application/pdf,.pdf" multiple @change="upload"/></div></div><div class="library-workbench"><section class="document-table-panel"><div class="table-filters"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索本库题名或文件名" aria-label="搜索本库文献" clearable/><el-select v-model="status" aria-label="处理状态"><el-option label="全部状态" value="all"/><el-option label="正在处理" value="processing"/><el-option label="需要关注" value="needs_attention"/><el-option label="已就绪" value="ready"/><el-option label="正在解析" value="parsing"/><el-option label="建立索引" value="indexing"/><el-option label="处理失败" value="failed"/><el-option label="重建待恢复" value="reindexing"/><el-option label="重建未完成" value="reindex_failed"/></el-select></div><el-table :data="paged" v-loading="loading" row-key="id" highlight-current-row @selection-change="setSelection" @row-click="focusDocument" empty-text="暂无匹配文献，上传 PDF 或调整筛选条件。"><el-table-column type="selection" width="42" :selectable="selectableDocument"/><el-table-column label="论文" min-width="220"><template #default="{ row }"><div class="table-paper"><span class="file-symbol"><el-icon><Document/></el-icon></span><div><strong>{{ row.paper_title || row.filename }}</strong><small>{{ row.filename }}</small></div></div></template></el-table-column><el-table-column label="状态" width="96"><template #default="{ row }"><span :class="['document-status', { ready: row.status === 'ready', attention: documentStatusGroup(row.status) === 'needs_attention' }]"><span class="tiny-dot"></span>{{ statusLabels[row.status] || row.status }}</span></template></el-table-column><el-table-column label="片段" width="65"><template #default="{ row }"><span class="muted-text">{{ row.num_chunks || '—' }}</span></template></el-table-column></el-table><div class="table-footer"><span>{{ filtered.length }} 篇文献</span><el-pagination v-model:current-page="page" :page-size="15" :total="filtered.length" layout="prev, pager, next" size="small" hide-on-single-page/></div><div v-if="!documents.length && writable" class="upload-nudge"><el-icon><Upload/></el-icon><strong>上传你的第一篇论文</strong><p>支持多选 PDF，每篇不超过 {{ ws.config?.max_pdf_mb || 50 }} MB。</p><el-button @click="fileInput?.click()">选择 PDF 文件</el-button></div></section><aside class="document-detail-panel"><template v-if="detail"><div class="document-detail-header"><span class="small-label">文献详情</span><h3>{{ detail.paper_title || detail.filename }}</h3><p>{{ detail.filename }}</p><div class="evidence-tabs"><button :class="{ active: detailTab === 'summary' }" @click="detailTab = 'summary'">摘要与状态</button><button :class="{ active: detailTab === 'pdf' }" @click="detailTab = 'pdf'">原文预览</button></div></div><div v-if="detailTab === 'summary'" class="document-summary"><span class="evidence-badge fulltext">{{ statusLabels[detail.status] || detail.status }}</span><h4>文献摘要</h4><p>{{ detail.summary || '暂未生成摘要。处理状态和原文仍可在这里查看。' }}</p><div class="document-facts"><div><span>文献库</span><strong>{{ library.title }}</strong></div><div><span>索引片段</span><strong>{{ detail.num_chunks || 0 }} 个</strong></div><div><span>库内序号</span><strong>{{ detail.library_index || '—' }}</strong></div></div><el-button v-if="detail.status === 'ready'" class="width-full" @click="selected = [detail]; study()">围绕这篇论文研读<el-icon><ArrowRight/></el-icon></el-button><IndexMaintenance :key="detail.id" :doc-id="detail.id" :status="detail.status" :writable="!!writable"/></div><PdfViewer v-else :url="`/api/documents/${detail.id}/pdf`" :title="detail.paper_title || detail.filename"/></template><div v-else class="side-empty"><el-icon><Document/></el-icon><h3>选择文献查看详情</h3><p>摘要、状态与原文会显示在这里。</p></div></aside></div></template><el-dialog v-model="createDialog" title="创建文献库" width="460px"><el-form label-position="top" @submit.prevent="create"><el-form-item label="文献库名称"><el-input v-model="title" placeholder="例如：超导材料与失超研究" maxlength="120"/></el-form-item><el-checkbox v-model="shared">设为课题组共享库</el-checkbox><p class="field-note">{{ shared ? '创建后，可按账号授予成员阅读或编辑权限。' : '只有你可以访问这个文献库。' }}</p></el-form><template #footer><el-button @click="createDialog = false">取消</el-button><el-button type="primary" :disabled="!title.trim()" :loading="creating" @click="create">创建文献库</el-button></template></el-dialog><el-dialog v-model="memberDialog" title="共享库成员" width="540px"><p class="dialog-description">{{ library?.title }} · 只有所有者可以管理成员。</p><el-table :data="members" empty-text="尚未添加成员"><el-table-column prop="username" label="账号"/><el-table-column label="权限"><template #default="{ row }">{{ row.role === 'editor' ? '可阅读与上传' : '只读' }}</template></el-table-column><el-table-column width="70"><template #default="{ row }"><el-button text type="danger" @click="removeMember(row.user_id)">移除</el-button></template></el-table-column></el-table><div class="member-add"><el-input v-model="memberName" placeholder="已有成员用户名"/><el-select v-model="memberRole"><el-option label="只读" value="viewer"/><el-option label="可编辑" value="editor"/></el-select><el-button type="primary" :disabled="!memberName.trim()" :loading="memberBusy" @click="addMember">添加</el-button></div></el-dialog></div></template>

<style scoped>
.document-status.attention { color: #946d32; }
.document-status.attention .tiny-dot { background: #bd944e; }
</style>
